package com.integrydt.backend.controller;

import com.fasterxml.jackson.databind.ObjectMapper;import com.integrydt.backend.service.DeviceTokenService;import jakarta.servlet.http.HttpServletRequest;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.web.bind.annotation.*;
import java.io.*;import java.nio.file.*;import java.security.*;import java.sql.Timestamp;import java.time.*;import java.util.*;import java.util.HexFormat;

@RestController @RequestMapping("/api/v1/agent/job-artifacts")
public class AgentArtifactsController {
 private static final long MAX=250L*1024*1024;private final JdbcTemplate db;private final DeviceTokenService tokens;private final ObjectMapper json;private final Path storageRoot;private final int retentionDays;
 public AgentArtifactsController(JdbcTemplate db,DeviceTokenService tokens,ObjectMapper json,@Value("${integry.artifact-storage}") String root,@Value("${integry.artifact-retention-days:7}") int days){this.db=db;this.tokens=tokens;this.json=json;this.storageRoot=Paths.get(root).toAbsolutePath().normalize();this.retentionDays=Math.max(1,Math.min(365,days));}
 @PostMapping("/{jobId}") public ResponseEntity<?> upload(@PathVariable String jobId,@RequestParam String deviceId,HttpServletRequest req)throws Exception{String auth=req.getHeader("Authorization");if(auth==null||!auth.regionMatches(true,0,"Bearer ",0,7)||!tokens.validate(deviceId,auth.substring(7)))return ResponseEntity.status(401).build();long declared=req.getContentLengthLong();if(declared>MAX)return ResponseEntity.status(413).build();var jobs=db.queryForList("SELECT CAST(j.company_id AS CHAR) companyId,CAST(j.device_id AS CHAR) deviceId,j.status,t.code toolCode FROM jobs j JOIN tools t ON t.id=j.tool_id WHERE j.id=? AND j.device_id=?",jobId,deviceId);if(jobs.isEmpty()||!Set.of("running","downloading_gadget").contains(jobs.get(0).get("status")))return ResponseEntity.notFound().build();var job=jobs.get(0);String requested=req.getHeader("X-Artifact-Name");String filename=safeName(requested==null||requested.isBlank()?"artifact.bin":requested);String id=UUID.randomUUID().toString();Path dir=storageRoot.resolve((String)job.get("companyId")).resolve(jobId).normalize();if(!dir.startsWith(storageRoot))return ResponseEntity.badRequest().build();Files.createDirectories(dir);Path target=dir.resolve(id+"-"+filename).normalize();long size=0;try(InputStream in=req.getInputStream();OutputStream out=Files.newOutputStream(target,StandardOpenOption.CREATE_NEW)){byte[] buf=new byte[81920];for(int n;(n=in.read(buf))>=0;){if(n==0)continue;size+=n;if(size>MAX)throw new IOException("artifact_too_large");out.write(buf,0,n);}}catch(Exception e){Files.deleteIfExists(target);if("artifact_too_large".equals(e.getMessage()))return ResponseEntity.status(413).body(Map.of("error","artifact_too_large"));throw e;}String sha;try(InputStream in=Files.newInputStream(target)){sha=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(in.readAllBytes()));}Timestamp expires=Timestamp.from(Instant.now().plus(Duration.ofDays(retentionDays)));String ct=Optional.ofNullable(req.getContentType()).orElse("application/octet-stream");db.update("INSERT INTO job_artifacts(id,company_id,job_id,device_id,filename,storage_path,content_type,size_bytes,sha256,expires_at) VALUES(?,?,?,?,?,?,?,?,?,?)",id,job.get("companyId"),jobId,deviceId,filename,target.toString(),ct,size,sha,expires);db.update("INSERT INTO job_events(job_id,event_type,message,metadata_json) VALUES(?,'artifact_uploaded','Artifact securely uploaded',CAST(? AS JSON))",jobId,json.writeValueAsString(Map.of("artifactId",id,"filename",filename,"sizeBytes",size,"sha256",sha)));cleanup();return ResponseEntity.ok(Map.of("id",id,"filename",filename,"sizeBytes",size,"sha256",sha,"retentionDays",retentionDays));}
 private void cleanup(){var rows=db.queryForList("SELECT CAST(id AS CHAR) id,storage_path storagePath FROM job_artifacts WHERE expires_at IS NOT NULL AND expires_at<CURRENT_TIMESTAMP(6) LIMIT 50");for(var r:rows){try{Path p=Paths.get((String)r.get("storagePath")).toAbsolutePath().normalize();if(p.startsWith(storageRoot))Files.deleteIfExists(p);}catch(Exception ignored){}db.update("DELETE FROM job_artifacts WHERE id=?",r.get("id"));}}
 private static String safeName(String n){try{String x=Paths.get(n).getFileName().toString();return x.isBlank()?"artifact.bin":x;}catch(Exception e){return "artifact.bin";}}
}
